import { pchisq } from "../distributions/chisq.js";
import { levelText } from "../internal/levels.js";
import { ldexp, ldexpWide } from "../internal/summary.js";
import { reported } from "../internal/warnings.js";
import { solve } from "../linalg/solve.js";
import type { CoxphResult, CoxphZphData } from "./coxph.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const COX_ZPH_KEYS = ["transform", "terms", "collapseTerms", "global"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)


/** Transform names and custom functions accepted by coxZph.
 * @category Survival analysis
 */
export type CoxZphTransform = "km" | "rank" | "identity" | "log" | ((times: readonly number[]) => readonly number[]);

/** Term grouping accepted by coxZph; use `collapseTerms: false` to retain individual columns within groups.
 * @category Survival analysis
 */
export type CoxZphTerms = readonly (readonly number[])[] | false;

/**
 * Options for Schoenfeld-residual tests of proportional hazards.
 *
 * @category Survival analysis
 */
export interface CoxZphOptions {
  /** Transform of the merged stop times. Default `"km"`; a function receives all used rows in input order. */
  transform?: CoxZphTransform;
  /** Zero-based column groups defining formula terms; false makes each column its own term. A multi-column group is collapsed by default. */
  terms?: CoxZphTerms;
  /** Keep grouped columns separate in y, var and the test table. Default true. */
  collapseTerms?: boolean;
  /** Include the global test row. Default true. */
  global?: boolean;
}

/**
 * Result of the proportional-hazards test.
 *
 * @category Survival analysis
 */
export interface CoxZphResult {
  /** Names of the tested terms, with GLOBAL last when requested. */
  rowNames: string[];
  /** Chi-squared statistics, with GLOBAL last when requested. */
  chisq: number[];
  /** Degrees of freedom. */
  df: number[];
  /** Upper chi-squared probabilities. */
  p: number[];
  /** Alias of p. */
  pValue: number[];
  /** Transformed times at the event rows. */
  x: number[];
  /** Event times in the fit's merged time scale. */
  time: number[];
  /** Stratum labels at event rows, only when the fit had strata. */
  strata?: string[];
  /** Scaled Schoenfeld residuals, one row per event. */
  y: number[][];
  /** Variance matrix for y. */
  var: number[][];
  /** Transform used. */
  transform: CoxZphTransform;
  /** Warnings of the fit and this call. */
  warnings: string[];
}

interface EventRecord {
  input: number;
  time: number;
  stratum: number;
  g: number;
  residual: number[];
}

const zeros = (n: number): number[] => new Array<number>(n).fill(0);
const square = (n: number): number[][] => Array.from({ length: n }, () => zeros(n));

function rankAverage(values: readonly number[]): number[] {
  const order = Array.from({ length: values.length }, (_, i) => i).sort((a, b) => values[a]! - values[b]! || a - b);
  const out = new Array<number>(values.length);
  for (let i = 0; i < order.length; ) {
    let j = i + 1;
    while (j < order.length && values[order[j]!] === values[order[i]!]) j++;
    const rank = (i + 1 + j) / 2;
    for (let k = i; k < j; k++) out[order[k]!] = rank;
    i = j;
  }
  return out;
}

function lowerBound(sorted: readonly number[], value: number): number {
  let lo = 0;
  let hi = sorted.length;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (sorted[mid]! < value) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

function kmTransform(data: CoxphZphData): number[] {
  const n = data.time.length;
  const out = new Array<number>(n);
  const byTime = new Map<number, { rows: number[]; deaths: number }>();
  for (let i = 0; i < n; i++) {
    const t = data.time[i]!;
    const group = byTime.get(t) ?? { rows: [], deaths: 0 };
    group.rows.push(i);
    if (data.status[i]) group.deaths++;
    byTime.set(t, group);
  }
  const times = [...byTime.keys()].sort((a, b) => a - b);
  const sortedStop = data.time.slice().sort((a, b) => a - b);
  const sortedStart = (data.start ?? new Array<number>(n).fill(-Infinity)).slice().sort((a, b) => a - b);
  let survival = 1;
  for (const t of times) {
    const group = byTime.get(t)!;
    for (const i of group.rows) out[i] = 1 - survival;
    const risk = lowerBound(sortedStart, t) - lowerBound(sortedStop, t);
    if (group.deaths > 0) survival *= 1 - group.deaths / risk;
  }
  return out;
}

function transformTimes(
  data: CoxphZphData,
  transform: CoxZphTransform,
  eventInput: readonly number[],
  warnings: string[],
): number[] {
  let values: number[];
  if (typeof transform === "function") {
    const returned = transform(data.time.slice());
    if (!Array.isArray(returned) || returned.length !== data.time.length) {
      throw new RangeError("transform function must return one value per observation");
    }
    values = Array.from(returned);
  } else if (transform === "km") {
    values = kmTransform(data);
  } else if (transform === "rank") {
    values = rankAverage(data.time);
  } else if (transform === "identity") {
    values = data.time.slice();
  } else if (transform === "log") {
    if (data.time.some((t) => t < 0)) warnings.push("NaNs produced");
    values = data.time.map(Math.log);
  } else {
    throw new RangeError("Unrecognized transform");
  }
  for (const i of eventInput) {
    if (!Number.isFinite(values[i]!)) throw new RangeError("transform must be finite at every event time");
  }
  return values;
}

/**
 * Tests the proportional-hazards assumption using the score test of Grambsch and Therneau (1994).
 * Equivalent to R's `survival::cox.zph()`. The fit retains its processed rows privately, so no refit is performed; robust and clustered
 * variances of the fit are not used.
 *
 * @param fit A result returned by `coxph`.
 * @param options See {@link CoxZphOptions}.
 * @throws Error for no events, fewer than two distinct event times, a constant transform, or singular information.
 *
 * @category Survival analysis
 */
export function coxZph(fit: CoxphResult, options: CoxZphOptions = {}): CoxZphResult {
  checkOptions(options, COX_ZPH_KEYS, "coxZph"); // generated: option-keys.mjs
  checkOptions(options, COX_ZPH_KEYS, "coxZph");
  const transform = options.transform ?? "km";
  const global = options.global ?? true;
  const collapse = options.collapseTerms ?? true;
  if (typeof global !== "boolean") throw new TypeError("'global' must be a boolean");
  if (typeof collapse !== "boolean") throw new TypeError("'collapseTerms' must be a boolean");
  if (options.terms !== undefined && options.terms !== false && !Array.isArray(options.terms)) {
    throw new TypeError("'terms' must be an array of column groups or false");
  }
  if (fit.nevent === 0) throw new Error("the proportional-hazards test requires events");
  const data = fit.coxZphData;
  if (data === undefined) throw new TypeError("coxZph requires a CoxphResult returned by coxph");

  const columns = fit.coefficients.map((v, i) => (Number.isNaN(v) ? -1 : i)).filter((i) => i >= 0);
  const p = columns.length;
  if (p === 0) throw new Error("the proportional-hazards test has no estimable coefficients");

  const eventInput: number[] = [];
  for (let lo = 0; lo < data.sortedTime.length; ) {
    let hi = lo;
    while (!data.stratumEnd[hi]) hi++;
    for (let i = lo; i <= hi; ) {
      const t = data.sortedTime[i]!;
      let end = i;
      while (end < hi && data.sortedTime[end + 1] === t) end++;
      const deaths: number[] = [];
      for (let j = i; j <= end; j++) if (data.sortedEvent[j]) deaths.push(j);
      if (data.start !== undefined) deaths.reverse();
      for (const j of deaths) eventInput.push(data.sortedToInput[j]!);
      i = end + 1;
    }
    lo = hi + 1;
  }
  if (eventInput.length === 0) throw new Error("the proportional-hazards test requires events");
  const eventTimes = eventInput.map((i) => data.time[i]!);
  if (new Set(eventTimes).size < 2) throw new Error("the test needs events at two or more distinct times");

  const warnings = [...fit.warnings];
  const gInput = transformTimes(data, transform, eventInput, warnings);
  const firstEventG = gInput[eventInput[0]!]!;
  if (eventInput.every((i) => gInput[i] === firstEventG)) {
    throw new Error("the transform is constant at the event times");
  }
  const maxG = eventInput.reduce((max, i) => Math.max(max, Math.abs(gInput[i]!)), 0);
  const gExp = maxG === 0 ? 0 : Math.floor(Math.log2(maxG));
  const gScaled = gInput.map((v) => (Number.isFinite(v) ? ldexp(v, -gExp) : v));
  const gMean = eventInput.reduce((sum, i) => sum + gScaled[i]!, 0) / eventInput.length;
  const gCentered = gScaled.map((v) => v - gMean);
  if (eventInput.every((i) => gCentered[i] === 0)) throw new Error("the transform is constant at the event times");

  const beta = columns.map((j) => data.betaScaled[j]!);
  const info = square(p);
  const cross = square(p);
  const thetaInfo = square(p);
  const U = zeros(p);
  const events: EventRecord[] = [];

  for (let lo = 0; lo < data.sortedTime.length; ) {
    let hi = lo;
    while (!data.stratumEnd[hi]) hi++;
    for (let i = lo; i <= hi; ) {
      const t = data.sortedTime[i]!;
      let end = i;
      while (end < hi && data.sortedTime[end + 1] === t) end++;
      const deaths: number[] = [];
      for (let j = i; j <= end; j++) if (data.sortedEvent[j]) deaths.push(j);
      if (deaths.length > 0) {
        const risk: number[] = [];
        let shift = -Infinity;
        for (let j = lo; j <= hi; j++) {
          const atRisk = data.sortedStart === undefined
            ? data.sortedTime[j]! >= t
            : data.sortedStart[j]! < t && data.sortedTime[j]! >= t;
          if (!atRisk) continue;
          risk.push(j);
          let eta = 0;
          for (let k = 0; k < p; k++) eta += beta[k]! * data.sortedX[j]![columns[k]!]!;
          shift = Math.max(shift, eta);
        }
        if (risk.length === 0 || !Number.isFinite(shift)) throw new Error("empty Cox proportional-hazards risk set");

        const S1 = zeros(p);
        const S2 = square(p);
        const E1 = zeros(p);
        const E2 = square(p);
        let S0 = 0;
        let E0 = 0;
        for (const j of risk) {
          let eta = 0;
          for (let k = 0; k < p; k++) eta += beta[k]! * data.sortedX[j]![columns[k]!]!;
          const wr = data.sortedWeight[j]! * Math.exp(eta - shift);
          S0 += wr;
          for (let a = 0; a < p; a++) {
            const xa = data.sortedX[j]![columns[a]!]!;
            S1[a]! += wr * xa;
            for (let b = 0; b < p; b++) S2[a]![b]! += wr * xa * data.sortedX[j]![columns[b]!]!;
          }
          if (data.sortedEvent[j] && data.sortedTime[j] === t) {
            E0 += wr;
            for (let a = 0; a < p; a++) {
              const xa = data.sortedX[j]![columns[a]!]!;
              E1[a]! += wr * xa;
              for (let b = 0; b < p; b++) E2[a]![b]! += wr * xa * data.sortedX[j]![columns[b]!]!;
            }
          }
        }
        let dw = 0;
        const eventSum = zeros(p);
        for (const j of deaths) {
          const w = data.sortedWeight[j]!;
          dw += w;
          for (let a = 0; a < p; a++) eventSum[a]! += w * data.sortedX[j]![columns[a]!]!;
        }
        const d = deaths.length;
        const steps = data.ties === "efron" && d > 1 ? d : 1;
        const xbar = zeros(p);
        const V = square(p);
        for (let m = 0; m < steps; m++) {
          const f = m / steps;
          const denom = S0 - f * E0;
          const xb = S1.map((v, k) => (v - f * E1[k]!) / denom);
          for (let a = 0; a < p; a++) xbar[a]! += xb[a]! / steps;
          const factor = dw / steps;
          for (let a = 0; a < p; a++) for (let b = 0; b < p; b++) {
            V[a]![b]! += factor * ((S2[a]![b]! - f * E2[a]![b]!) / denom - xb[a]! * xb[b]!);
          }
        }
        const score = eventSum.map((v, k) => v - dw * xbar[k]!);
        const input = data.sortedToInput[deaths[0]!]!;
        const g = gCentered[input]!;
        for (let a = 0; a < p; a++) {
          U[a]! += g * score[a]!;
          for (let b = 0; b < p; b++) {
            info[a]![b]! += V[a]![b]!;
            cross[a]![b]! += g * V[a]![b]!;
            thetaInfo[a]![b]! += g * g * V[a]![b]!;
          }
        }
        if (data.start !== undefined) deaths.reverse();
        for (const j of deaths) {
          const rowInput = data.sortedToInput[j]!;
          const residual = columns.map((col) => data.sortedX[j]![col]!);
          for (let a = 0; a < p; a++) residual[a]! -= xbar[a]!;
          events.push({
            input: rowInput,
            time: t,
            stratum: data.stratumIndex[j]!,
            g: gInput[rowInput]!,
            residual,
          });
        }
      }
      i = end + 1;
    }
    lo = hi + 1;
  }

  let solved: number[][];
  try {
    solved = solve(info, cross) as number[][];
  } catch {
    throw new Error("the proportional-hazards information is singular");
  }
  const M = square(p);
  for (let a = 0; a < p; a++) for (let b = 0; b < p; b++) {
    let correction = 0;
    for (let k = 0; k < p; k++) correction += cross[k]![a]! * solved[k]![b]!;
    M[a]![b] = thetaInfo[a]![b]! - correction;
  }
  for (let a = 0; a < p; a++) for (let b = 0; b < a; b++) {
    const v = (M[a]![b]! + M[b]![a]!) / 2;
    M[a]![b] = v;
    M[b]![a] = v;
  }

  const sourceGroups: readonly (readonly number[])[] =
    options.terms === false || options.terms === undefined ? columns.map((j) => [j]) : options.terms;
  const seen = new Set<number>();
  const groups: number[][] = [];
  const groupSourceIndex: number[] = [];
  sourceGroups.forEach((group, gi) => {
    if (!Array.isArray(group) || group.length === 0) throw new RangeError("each terms group must be a non-empty array");
    const kept: number[] = [];
    for (const col of group) {
      if (!Number.isInteger(col) || col < 0 || col >= fit.coefficients.length) {
        throw new RangeError("terms column indices must be zero-based and within x");
      }
      if (seen.has(col)) throw new RangeError("terms groups must not overlap");
      seen.add(col);
      if (columns.includes(col)) kept.push(col);
    }
    if (kept.length > 0) {
      groups.push(kept);
      groupSourceIndex.push(gi);
    }
  });
  columns.forEach((col) => {
    if (!seen.has(col)) {
      groups.push([col]);
      groupSourceIndex.push(sourceGroups.length);
    }
  });
  if (groups.length === 0) throw new Error("the proportional-hazards test has no estimable terms");

  const expanded: { col: number; group: number; collapsed: boolean }[] = [];
  groups.forEach((group, gi) => {
    if (collapse && group.length > 1) {
      expanded.push({ col: -1, group: gi, collapsed: true });
    } else {
      for (const col of group) expanded.push({ col, group: gi, collapsed: false });
    }
  });
  const q = expanded.length;
  const L = Array.from({ length: p }, () => zeros(q));
  const intercept: number[] = [];
  const rowNames: string[] = [];
  expanded.forEach((term, j) => {
    const group = groups[term.group]!;
    const sourceIndex = groupSourceIndex[term.group]!;
    if (term.collapsed) {
      for (const col of group) {
        const k = columns.indexOf(col);
        L[k]![j] = beta[k]!;
      }
      intercept.push(1);
      rowNames.push(`g${sourceIndex + 1}`);
    } else {
      const k = columns.indexOf(term.col);
      L[k]![j] = data.inverseCovariateScale[term.col]!;
      intercept.push(fit.coefficients[term.col]!);
      rowNames.push(group.length > 1 ? `g${sourceIndex + 1}x${term.col + 1}` : `x${term.col + 1}`);
    }
  });

  // Scale each column of L by an exact power of two before forming L' I L. The terms can be in very different
  // covariate units (e.g. a covariate multiplied by 2^40); solving the unscaled J makes the condition check depend
  // on those units even though the test and the residuals are well-defined.
  const columnExp = Array.from({ length: q }, (_, j) => {
    let max = 0;
    for (let k = 0; k < p; k++) max = Math.max(max, Math.abs(L[k]![j]!));
    if (!(max > 0 && Number.isFinite(max))) throw new Error("the proportional-hazards residual variance is singular");
    return Math.floor(Math.log2(max));
  });
  const scaledL = L.map((row) => row.map((v, j) => ldexp(v, -columnExp[j]!)));
  const IL = Array.from({ length: p }, () => zeros(q));
  for (let a = 0; a < p; a++) for (let j = 0; j < q; j++) {
    for (let b = 0; b < p; b++) IL[a]![j]! += info[a]![b]! * scaledL[b]![j]!;
  }
  const J = square(q);
  for (let a = 0; a < q; a++) for (let b = 0; b < q; b++) {
    for (let k = 0; k < p; k++) J[a]![b]! += scaledL[k]![a]! * IL[k]![b]!;
  }
  for (let a = 0; a < q; a++) for (let b = 0; b < a; b++) {
    const v = (J[a]![b]! + J[b]![a]!) / 2;
    J[a]![b] = v;
    J[b]![a] = v;
  }
  let Jinv: number[][];
  try {
    Jinv = solve(J) as number[][];
  } catch {
    throw new Error("the proportional-hazards residual variance is singular");
  }
  for (let a = 0; a < q; a++) for (let b = 0; b < a; b++) {
    const v = (Jinv[a]![b]! + Jinv[b]![a]!) / 2;
    Jinv[a]![b] = v;
    Jinv[b]![a] = v;
  }
  // J_original^-1 = D J_scaled^-1 D, D_j = 2^-columnExp[j]. The fit's weights are
  // divided by 2^weightExp, so that exponent is restored here too.
  const variance = Jinv.map((row, i) =>
    row.map((v, j) => eventInput.length * ldexpWide(v, -columnExp[i]! - columnExp[j]! - data.weightExp)),
  );
  const y = events.map((event) => {
    const ls = zeros(q);
    for (let a = 0; a < q; a++) for (let k = 0; k < p; k++) ls[a]! += scaledL[k]![a]! * event.residual[k]!;
    return intercept.map((b, j) => {
      let delta = 0;
      for (let k = 0; k < q; k++) delta += ls[k]! * Jinv[k]![j]!;
      return b + eventInput.length * ldexpWide(delta, -columnExp[j]! - data.weightExp);
    });
  });

  // U and M above use weights divided by 2^weightExp. Since U' M^-1 U is linear in a common weight multiplier,
  // restore that factor for the reported score-test statistic (the y and var outputs restore its inverse below).
  const chisq: number[] = [];
  const df: number[] = [];
  const pValues: number[] = [];
  const testGroups = expanded.map((term) =>
    term.collapsed ? groups[term.group]!.map((col) => columns.indexOf(col)) : [columns.indexOf(term.col)],
  );
  for (const group of testGroups) {
    const sub = group.map((a) => group.map((b) => M[a]![b]!));
    const u = group.map((a) => U[a]!);
    let estimate: number[];
    try {
      estimate = solve(sub, u) as number[];
    } catch {
      throw new Error("the proportional-hazards term information is singular");
    }
    const stat = ldexp(Math.max(0, u.reduce((sum, v, i) => sum + v * estimate[i]!, 0)), data.weightExp);
    chisq.push(stat);
    df.push(group.length);
    pValues.push(pchisq(stat, group.length, { lowerTail: false }));
  }
  if (global) {
    let estimate: number[];
    try {
      estimate = solve(M, U) as number[];
    } catch {
      throw new Error("the global proportional-hazards information is singular");
    }
    const stat = ldexp(Math.max(0, U.reduce((sum, v, i) => sum + v * estimate[i]!, 0)), data.weightExp);
    chisq.push(stat);
    df.push(p);
    pValues.push(pchisq(stat, p, { lowerTail: false }));
    rowNames.push("GLOBAL");
  }

  const result: CoxZphResult = {
    rowNames,
    chisq,
    df,
    p: pValues,
    pValue: pValues,
    x: events.map((event) => event.g),
    time: events.map((event) => event.time),
    ...(data.strata === undefined ? {} : { strata: events.map((event) => levelText(data.strata![event.input]!)) }),
    y,
    var: variance,
    transform,
    warnings,
  };
  return reported("coxZph", result, fit);
}
